// Função para limpar a formatação Markdown básica
function cleanMarkdown(text) {
  if (!text || typeof text !== "string") return "";
  return text
    .replace(/\*\*(.*?)\*\*/g, "$1")    // Remove **negrito**
    .replace(/\*(.*?)\*/g, "$1")          // Remove *itálico*
    .replace(/###\s*(.*)/g, "\n$1")       // Ajusta títulos nível 3
    .replace(/##\s*(.*)/g, "\n$1")        // Ajusta títulos nível 2
    .replace(/#\s*(.*)/g, "\n$1")         // Ajusta títulos nível 1
    .trim();
}

// Função que converte o texto (com quebras de linha) em HTML,
// identificando itens de lista e seus subitens por meio da indentação.
// Linhas que não forem itens de lista são encapsuladas em parágrafos.
function convertMarkdownListsToHtmlNested(text) {
  const lines = text.split(/\r?\n/);
  let result = "";
  // Stack para controlar os níveis aninhados; cada item: { indent: number, type: "ul" ou "ol" }
  const stack = [];

  // Função auxiliar para fechar listas abertas até um determinado nível
  const closeListsUntil = (targetIndent) => {
    while (stack.length > 0 && stack[stack.length - 1].indent > targetIndent) {
      const popped = stack.pop();
      result += `</${popped.type}>\n`;
    }
  };

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.trim() === "") {
      // Linha em branco: fecha quaisquer listas abertas e insere uma quebra
      closeListsUntil(0);
      result += "\n";
      continue;
    }

    // Verifica se a linha é um item de lista não ordenada (usa "-" ou "•")
    const unorderedMatch = line.match(/^(\s*)[-•]\s+(.*)/);
    // Verifica se a linha é um item de lista ordenada (usa dígito seguido de ".")
    const orderedMatch = line.match(/^(\s*)(\d+)\.\s+(.*)/);

    // Se for um item e o conteúdo (após o marcador) estiver vazio, ignora-o
    if (unorderedMatch && unorderedMatch[2].trim() === "") continue;
    if (orderedMatch && orderedMatch[3].trim() === "") continue;

    if (unorderedMatch || orderedMatch) {
      // Define dados comuns
      let indent, content, listType;
      if (unorderedMatch) {
        indent = unorderedMatch[1].length;
        content = unorderedMatch[2];
        listType = "ul";
      } else {
        indent = orderedMatch[1].length;
        content = orderedMatch[3];
        listType = "ol";
      }

      // Se a pilha estiver vazia, inicia uma nova lista
      if (stack.length === 0) {
        result += `<${listType}>\n`;
        stack.push({ indent, type: listType });
      } else {
        const currentLevel = stack[stack.length - 1];
        if (indent > currentLevel.indent) {
          // Nível mais profundo: inicia uma nova lista aninhada
          result += `<${listType}>\n`;
          stack.push({ indent, type: listType });
        } else if (indent < currentLevel.indent) {
          // Volta para um nível superior: fecha as listas enquanto o nível for maior que o atual
          closeListsUntil(indent);
          // Se o tipo de lista for diferente do nível atual (ou se a pilha ficou vazia), inicia uma nova lista
          if (stack.length === 0 || stack[stack.length - 1].type !== listType) {
            result += `<${listType}>\n`;
            stack.push({ indent, type: listType });
          }
        } else {
          // Mesmo nível: se o tipo de lista mudar, fecha a anterior e abre a nova
          if (currentLevel.type !== listType) {
            stack.pop();
            result += `</${currentLevel.type}>\n`;
            result += `<${listType}>\n`;
            stack.push({ indent, type: listType });
          }
          // Caso contrário, permanece no mesmo nível
        }
      }
      // Adiciona o item da lista
      result += `<li>${content}</li>\n`;
    } else {
      // Linha que não é item de lista:
      // Fecha quaisquer listas em aberto antes de inserir um parágrafo
      closeListsUntil(0);
      result += `<p>${line.trim()}</p>\n`;
    }
  }

  // Fecha todas as listas que ainda estiverem abertas
  closeListsUntil(0);
  return result;
}

// --- Captura os textos dos nós de IA ---
const parecerCompletoRaw = $('Geração do Parecer Final e Pontuação').first().json.output || "";
const estimativaCustoRaw = $('Estimativa de Custo').first().json.output || "";
const avaliacaoRiscosRaw = $('Avaliação de Riscos do Projeto').first().json.output || "";
const alinhamentoPDIRaw = $('Análise de Adequação à Política de PDI').first().json.output || "";

// Aplica a limpeza do Markdown em cada texto
const parecerCompleto = cleanMarkdown(parecerCompletoRaw);
const estimativaCusto   = cleanMarkdown(estimativaCustoRaw);
const avaliacaoRiscos   = cleanMarkdown(avaliacaoRiscosRaw);
const alinhamentoPDI    = cleanMarkdown(alinhamentoPDIRaw);

// --- Extração da Nota Final ---
// Procura por "Nota Final", "Nota final (0-10)" ou "Nota" seguido de um valor numérico
const notaRegex = /(?:Nota Final|Nota final|Nota final \(0-10\)|Nota)\s*[:\-]?\s*(\d+)/i;
const notaMatch = parecerCompleto.match(notaRegex);
const notaFinal = notaMatch ? parseInt(notaMatch[1]) : null;
// Remove a parte referente à nota para evitar duplicidade
const parecerSemNota = parecerCompleto.replace(notaRegex, "").trim();

// --- Extração do Score de Custo ---
// Regex que captura variações como "Score de Custo", "Score de Custo do Projeto" ou "Score de custo (0-10):"
const scoreCustoRegex = /Score de Custo(?: do| de)?(?: Projeto)?\s*\(0-10\)\s*[:\-]?\s*(\d+)/i;
let scoreCustoMatch = 
  parecerCompleto.match(scoreCustoRegex) ||
  estimativaCusto.match(scoreCustoRegex) ||
  avaliacaoRiscos.match(scoreCustoRegex) ||
  alinhamentoPDI.match(scoreCustoRegex);
const scoreCusto = scoreCustoMatch ? parseInt(scoreCustoMatch[1]) : null;
// Remove a parte referente ao score dos textos
const parecerSemScore = parecerSemNota.replace(scoreCustoRegex, "").trim();
const estimativaCustoSemScore = estimativaCusto.replace(scoreCustoRegex, "").trim();

// --- Limpeza adicional: remove linhas que contenham apenas numeração (por exemplo, "3." ou "4.") ---
const parecerSemScoreClean = parecerSemScore.replace(/^\s*\d+\.\s*$/gm, "").trim();
const estimativaCustoClean = estimativaCustoSemScore.replace(/^\s*\d+\.\s*$/gm, "").trim();

// --- Converte os textos limpos para HTML com marcação de listas aninhadas ---
const alinhamentoPDI_html = convertMarkdownListsToHtmlNested(alinhamentoPDI || "Análise de alinhamento não encontrada.");
const avaliacaoRiscos_html = convertMarkdownListsToHtmlNested(avaliacaoRiscos || "Avaliação de riscos não encontrada.");
const estimativaCusto_html = convertMarkdownListsToHtmlNested(estimativaCustoClean || "Estimativa de custo não encontrada.");
const parecerFinal_html    = convertMarkdownListsToHtmlNested(parecerSemScoreClean || "Parecer não encontrado.");

// --- Retorna os valores organizados em variáveis separadas ---
return [{
    json: {
        "Alinhamento à Política de PDI": alinhamentoPDI_html,
        "Avaliação de Riscos": avaliacaoRiscos_html,
        "Estimativa de Custo": estimativaCusto_html,
        "Parecer Final": parecerFinal_html,
        "Nota": notaFinal !== null ? notaFinal : "Nota não encontrada.",
        "Score de Custo": scoreCusto !== null ? scoreCusto : "Score de custo não encontrado."
    }
}];

// Lógica da decisão sobre propostas de PD&I enviadas pelo site (fluxos "Submissão de Projeto de PDI" e
// "PD&I – Decisão de proposta"). Funções puras: montam o registro da proposta, as páginas HTML da decisão,
// o plano de criação no eLabFTW e os pedidos de e-mail para o subfluxo "Modal – Enviar e-mail".

const DIA = 24 * 3600e3;
const ACOES = {
  aprovar: { rotulo: 'Aprovar', status: 'aprovada' },
  complementar: { rotulo: 'Pedir complementação', status: 'complementacao' },
  rejeitar: { rotulo: 'Rejeitar', status: 'rejeitada' },
};

function esc(s) {
  return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

function texto(v, max = 4000) {
  return String(v ?? '').replace(/\r\n/g, '\n').trim().slice(0, max);
}

// ---------- registro da proposta (fluxo de submissão) ----------

function novaProposta({ dados, parecer, token, agora, cfg }) {
  if (!/^[a-f0-9]{48}$/.test(String(token))) throw new Error('Token inválido.');
  const g = (k) => texto(dados[k]);
  return {
    token,
    id_projeto: g('id_projeto'),
    titulo: g('Título do Projeto') || '(sem título)',
    proponente_nome: g('Nome do Proponente'),
    proponente_email: g('E-mail do Proponente').toLowerCase(),
    dados_json: JSON.stringify({
      area: g('Área Prioritária'),
      descricao: g('Descrição Resumida'),
      problema: g('Problema que o Projeto Pretende Resolver'),
      objetivos: g('Objetivos e Resultados Esperados'),
      equipe: g('Possui Equipe Definida'),
      prazo: g('Prazo Estimado'),
      parceiros: g('Existem Parceiros Externos Envolvidos?'),
      parceiros_detalhes: g('Detalhes sobre Parceiros'),
      nota: texto(parecer && parecer.nota, 40),
      vinculo_proponente: g('Vínculo do Proponente'),
      equipe_lista: Array.isArray(dados.Equipe) ? dados.Equipe.slice(0, 30) : [],
      dominio: g('Domínio de Aplicação'),
      tecnologias: g('Tecnologias Envolvidas'),
      abordagem: g('Abordagem Metodológica'),
      justificativa: g('Justificativa da Abordagem'),
      estado_arte: g('Estado da Arte e Inovação'),
      produtos: g('Produtos Previstos'),
      inicio: g('Início Previsto'),
      termino: g('Término Previsto'),
      vinculo_projeto: g('Vínculo do Projeto'),
      parceiro: g('Parceiro ou Financiador'),
      cuidados: g('Cuidados'),
      recursos_riscos: g('Recursos e Riscos'),
    }),
    status: 'pendente',
    criado_em: agora.toISOString(),
    expira_em: new Date(agora.getTime() + cfg.validadeDias * DIA).toISOString(),
    decisor: '',
    comentario: '',
    decidido_em: '',
    ficha_id: 0,
  };
}

function linkDecisao(token, cfg) {
  return `${cfg.urlWebhook}/webhook/${cfg.caminho}?t=${token}`;
}

// ---------- validação do link e da decisão ----------

function avaliarToken(registro, agora) {
  if (!registro || !registro.token) return { ok: false, motivo: 'inexistente' };
  if (registro.status !== 'pendente') return { ok: false, motivo: 'usado', status: registro.status };
  if (new Date(registro.expira_em) < agora) return { ok: false, motivo: 'vencido' };
  return { ok: true };
}

function validarDecisao(corpo) {
  const acao = String(corpo.acao || '');
  const comentario = texto(corpo.comentario, 3000);
  const decisor = texto(corpo.decisor, 120);
  if (!ACOES[acao]) return { ok: false, erro: 'Escolha uma das três decisões.' };
  if (!decisor) return { ok: false, erro: 'Informe o seu nome: ele fica registrado com a decisão.' };
  if (acao !== 'aprovar' && comentario.length < 10) return { ok: false, erro: 'Para pedir complementação ou rejeitar, escreva um comentário para o proponente (ao menos 10 caracteres).' };
  return { ok: true, acao, comentario, decisor };
}

// ---------- páginas HTML ----------

const ESTILO = `body{margin:0;background:#f4f6fa;font-family:Ubuntu,Lato,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#1f2033}
main{max-width:720px;margin:24px auto;background:#fff;border-radius:10px;padding:24px 20px;box-shadow:0 1px 4px rgba(0,0,77,.12)}
.marca{border-bottom:3px solid #ff9900;padding-bottom:12px;margin-bottom:16px}
.marca img{height:44px}h1{color:#00004d;font-size:22px;margin:8px 0 4px}h2{color:#00004d;font-size:16px;margin:20px 0 6px}
dl{margin:0}dt{font-weight:700;color:#00004d;margin-top:10px}dd{margin:2px 0 0;white-space:pre-line}
fieldset{border:1px solid #d2dae6;border-radius:8px;margin:16px 0;padding:12px}label{display:block;margin:8px 0;cursor:pointer}
textarea,input[type=text]{width:100%;box-sizing:border-box;border:1px solid #9aa5b8;border-radius:6px;padding:8px;font:inherit}
button{background:#ff9900;color:#00004d;border:0;border-radius:6px;padding:12px 20px;font-weight:700;font-size:16px;cursor:pointer}
.aviso{background:#fff3ec;border-left:4px solid #ff9900;padding:10px 12px;border-radius:4px}.erro{background:#fdecea;border-left-color:#c62828}
.mudo{color:#666;font-size:13px}@media (prefers-color-scheme:dark){body{background:#060a18}main{background:#0c1329;color:#ebf0fa}
h1,h2,dt{color:#9db8ff}.marca img{background:#fff;padding:4px;border-radius:4px}.aviso{background:#2a180e;color:#ebf0fa}textarea,input[type=text]{background:#141e3e;color:#ebf0fa}}`;

function pagina(titulo, corpoHtml, cfg) {
  return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex,nofollow"><title>${esc(titulo)}</title><style>${ESTILO}</style></head><body><main>
<div class="marca"><img src="${esc(cfg.logo)}" alt="Instituto Modal"></div>${corpoHtml}</main></body></html>`;
}

function paginaMensagem(titulo, mensagem, cfg, tom = '') {
  return pagina(titulo, `<h1>${esc(titulo)}</h1><p class="aviso ${tom}">${esc(mensagem)}</p>`, cfg);
}

const MOTIVOS = {
  inexistente: 'Este link de decisão não existe ou foi digitado errado.',
  usado: 'Esta proposta já foi decidida. Nada foi alterado.',
  vencido: 'Este link de decisão venceu. Peça ao proponente que envie a proposta de novo pelo formulário do site.',
};

function paginaToken(motivo, cfg) {
  return paginaMensagem('Link de decisão indisponível', MOTIVOS[motivo] || MOTIVOS.inexistente, cfg, 'erro');
}

