  const corpo = `<h1>Decisão sobre proposta de PD&amp;I</h1>
<p class="mudo">Abrir esta página não decide nada. A decisão só vale ao clicar em "Registrar decisão". O link vale para uma única decisão, até ${esc(new Date(registro.expira_em).toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }))}.</p>
${erro ? `<p class="aviso erro">${esc(erro)}</p>` : ''}
<h2>${esc(registro.titulo)}</h2><dl>
${item('Proponente', `${registro.proponente_nome} (${registro.proponente_email})`)}${item('Área prioritária', d.area)}
${item('Descrição resumida', d.descricao)}${item('Problema', d.problema)}${item('Objetivos e resultados esperados', d.objetivos)}
${item('Abordagem metodológica', [d.abordagem, d.justificativa].filter(Boolean).join(' — '))}${item('Produtos previstos', d.produtos)}
${item('Período', [d.inicio, d.termino].filter(Boolean).join(' a '))}${item('Vínculo', [d.vinculo_projeto, d.parceiro].filter(Boolean).join(' — '))}
${item('Cuidados declarados', d.cuidados)}${item('Equipe', (d.equipe_lista || []).map((p) => [p.nome, p.papel].filter(Boolean).join(' — ')).join('; '))}
${item('Nota do parecer automático', d.nota)}</dl>
<p class="mudo">A análise completa (adequação, riscos, custo e parecer) está no e-mail enviado a pdi@modal.org.br e na planilha de propostas.</p>
<form method="post" action="${esc(`${cfg.urlWebhook}/webhook/${cfg.caminhoRegistro}`)}">
<input type="hidden" name="t" value="${esc(registro.token)}">
<fieldset><legend>Decisão</legend>
<label><input type="radio" name="acao" value="aprovar" required> <strong>Aprovar</strong> — cria a ficha do projeto no eLabFTW, a conta e o grupo do proponente, e avisa o proponente.</label>
<label><input type="radio" name="acao" value="complementar"> <strong>Pedir complementação</strong> — o proponente recebe o seu comentário e envia a proposta de novo.</label>
