  { tipo: 'subtitulo', texto: 'Estimativa de custo' }, { tipo: 'paragrafo', texto: r['Estimativa de Custo'] },
] } }];

// Função para gerar um UUID manualmente
function generateUUID() {
  let dt = new Date().getTime();
  const uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    let r = (dt + Math.random() * 16) % 16 | 0;
    dt = Math.floor(dt / 16);
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
  return uuid;
}

// Captura os dados do formulário
const submissionTime = $json.body.entry_time;
const email = $json.body.email_1;

// Gera um ID único
const idProjeto = generateUUID();

// Retorna o ID junto com os dados originais
return [{
  json: {
    id_projeto: idProjeto,
    submissionTime: submissionTime,
    email: email,
    ...$json.body  // Mantém os dados originais
  }
}];

// Lógica do nó "Organiza Dados" do fluxo "Submissão de Projeto de PDI" (formulário de 20/11/2026).
// Recebe o corpo enviado pelo Forminator e devolve os dados com nomes legíveis. Mantém os nomes do formulário
// antigo que a análise por IA, a planilha e o e-mail ainda leem, preenchidos a partir dos campos novos.

const CAMPOS_EQUIPE = { text_2: 'nome', email_1: 'email', select_1: 'papel' };

function limpo(v, max = 4000) {
  if (Array.isArray(v)) v = v.join(', ');
  return String(v ?? '').replace(/\r\n/g, '\n').trim().slice(0, max);
}

// Repetidor do Forminator: o primeiro conjunto vem como text_2, os seguintes com sufixo (text_2-2, text_2_2...).
function equipeDe(corpo) {
  const pessoas = new Map();
  for (const [chave, valor] of Object.entries(corpo || {})) {
    const m = /^(text_2|email_1|select_1)(?:[-_](\d+))?$/.exec(chave);
    if (!m) continue;
    const n = m[2] || '1';
    const p = pessoas.get(n) || {};
    p[CAMPOS_EQUIPE[m[1]]] = limpo(valor, 200);
    pessoas.set(n, p);
  }
  return [...pessoas.entries()]
    .sort((a, b) => Number(a[0]) - Number(b[0]))
    .map(([, p]) => ({ nome: p.nome || '', email: (p.email || '').toLowerCase(), papel: p.papel || '' }))
    .filter((p) => p.nome || p.email);
}

function organizarProposta({ corpo, idProjeto }) {
  const c = corpo || {};
  const g = (k, max) => limpo(c[k], max);
  const equipe = equipeDe(c);
  const cuidados = g('checkbox_3');
  const vinculo = g('radio_2');
  const parceiro = g('text_5', 250);
  const comParceiro = /parceiro|fomento/i.test(vinculo);
  const periodo = [g('date_1'), g('date_2')].filter(Boolean).join(' a ');
  const dominio = g('select_2');
  const tecnologias = g('checkbox_1');
  const equipeTexto = equipe.map((p) => `${p.nome}${p.email ? ` (${p.email})` : ''}${p.papel ? ` — ${p.papel}` : ''}`).join('; ');
  return {
    id_projeto: idProjeto,
    'Data de Envio': g('entry_time'),
    // campos do formulário novo
    'Nome do Proponente': g('text_1', 200),
    'E-mail do Proponente': g('hidden_1', 200).toLowerCase(),
    'Vínculo do Proponente': g('radio_1'),
    Equipe: equipe,
    'Equipe (texto)': equipeTexto,
    'Título do Projeto': g('text_3', 150),
    'Domínio de Aplicação': dominio,
    'Tecnologias Envolvidas': tecnologias,
    'Problema e Pergunta de Pesquisa': g('textarea_1'),
    'Objetivos e Resultados Esperados': g('textarea_2'),
    'Abordagem Metodológica': g('select_3'),
    'Justificativa da Abordagem': g('text_4', 300),
    'Estado da Arte e Inovação': g('textarea_3'),
    'Produtos Previstos': g('checkbox_2'),
    'Início Previsto': g('date_1'),
    'Término Previsto': g('date_2'),
    'Vínculo do Projeto': vinculo,
    'Parceiro ou Financiador': parceiro,
    Cuidados: cuidados,
    'Recursos e Riscos': g('textarea_4'),
    // nomes do formulário antigo, ainda lidos pela análise, pela planilha e pelo e-mail
    'Telefone do Proponente': '',
    'Setor / Departamento': g('radio_1'),
    'Possui Equipe Definida': equipe.length ? 'Sim' : 'Não',
    'Área Prioritária': [dominio, tecnologias].filter(Boolean).join(' — '),
    'Descrição Resumida': g('textarea_1'),
    'Problema que o Projeto Pretende Resolver': g('textarea_1'),
    'Alinhamento com as Prioridades do Instituto Modal': `Domínio: ${dominio || '-'}; tecnologias: ${tecnologias || '-'}`,
    'Recursos Necessários': g('textarea_4'),
    'Infraestrutura ou Equipamentos Específicos': '',
    'Viabilidade Técnica': '',
    'Prazo Estimado': periodo,
    'Viabilidade Financeira': '',
    'Fontes de Financiamento': [vinculo, parceiro].filter(Boolean).join(' — '),
    'Principais Riscos e Desafios': g('textarea_4'),
    'Plano de Mitigação de Riscos': '',
    'Possível Geração de Propriedade Intelectual?': /propriedade intelectual/i.test(cuidados) ? 'Sim' : 'Não indicado',
    'Tipo de Propriedade Intelectual': '',
    'Existem Parceiros Externos Envolvidos?': comParceiro ? 'Sim' : 'Não',
    'Detalhes sobre Parceiros': comParceiro ? parceiro : '',
    'Comentários Adicionais': '',
    'Documentação Complementar': g('upload_1', 1000),
  };
}


const corpo = $('Captura Dados do Form').first().json.body || {};
return [{ json: organizarProposta({ corpo, idProjeto: $('Gera id_projeto').first().json.id_projeto }) }];

